{
  "findings": [
    {
      "id": "f1",
      "severity": "blocker",
      "title": "Отсутствует описанная окружность",
      "detail": "В условии явно требуется описать окружность вокруг треугольника, но на чертеже она не нарисована.",
      "fix_hint": "Вычислить радиус и центр описанной окружности и добавить её отрисовку (например, с помощью plt.Circle)."
    },
    {
      "id": "f2",
      "severity": "blocker",
      "title": "Отсутствует высота AH1 и точка H1",
      "detail": "В условии сказано провести высоту AH1 из вершины A на сторону BC, однако ни сам отрезок высоты, ни точка H1 на чертеже не представлены.",
      "fix_hint": "Найти координаты проекции точки A на прямую BC, отметить точку H1 и провести отрезок AH1."
    },
    {
      "id": "f3",
      "severity": "blocker",
      "title": "Отсутствует отрезок OM",
      "detail": "Условие требует провести отрезок OM, но на графике он не нарисован.",
      "fix_hint": "Добавить отрисовку линии, соединяющей точки O и M."
    },
    {
      "id": "f4",
      "severity": "major",
      "title": "Математически неверное положение ортоцентра H",
      "detail": "Точка H задана произвольными координатами и не является точкой пересечения высот. В данном треугольнике высота из A падает на x=0, а точка H имеет координату x=0.5.",
      "fix_hint": "Аналитически вычислить координаты ортоцентра (точки пересечения высот) для заданных вершин A, B, C и использовать их."
    },
    {
      "id": "f5",
      "severity": "major",
      "title": "Математически неверное положение центра описанной окружности O",
      "detail": "Точка O задана произвольно (визуально лежит на стороне AB) и не является центром описанной окружности. Она должна лежать на серединном перпендикуляре к BC (x=0.25), но имеет координату x=-1.5.",
      "fix_hint": "Аналитически вычислить координаты центра описанной окружности (точки пересечения серединных перпендикуляров) и поместить точку O туда."
    }
  ]
}
